import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { after, before, test } from 'node:test';
import { startRuntime, type RunningRuntime } from '../src/app.ts';
import { designPermission } from '../src/acp/session-manager.ts';

// Design Studio runs: a real (scripted) agent session writes HTML files into the
// board folder, and those files become frames. Nothing is generated by the runtime.

const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'myaos-design-'));
const workRoot = path.join(dir, 'work');
fs.mkdirSync(workRoot, { recursive: true });
const fixture = new URL('./fixtures/fake-acp-agent.mjs', import.meta.url).pathname;
const savedHome = process.env.MYAOS_HOME;
let rt: RunningRuntime;
let boardId = '';

const call = async (method: string, route: string, body?: unknown) => {
  const res = await fetch(`${rt.url}${route}`, {
    method,
    headers: { Authorization: `Bearer ${rt.token}`, ...(body ? { 'Content-Type': 'application/json' } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  return { status: res.status, json: (await res.json().catch(() => null)) as any };
};

const waitFor = async <T>(fn: () => Promise<T | null | undefined>, timeoutMs = 20_000): Promise<T> => {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const value = await fn();
    if (value) return value;
    await new Promise((r) => setTimeout(r, 150));
  }
  throw new Error('timed out waiting for condition');
};

before(async () => {
  process.env.MYAOS_HOME = path.join(dir, 'home');
  rt = await startRuntime({
    dbPath: path.join(dir, 'runtime.db'),
    workspaceRoots: [workRoot],
    worktreeRoot: path.join(dir, 'worktrees'),
    artifactsDir: path.join(dir, 'artifacts'),
  });
  await call('POST', '/v1/import/identities', {
    owner: { id: 'winston', name: 'Winston' },
    teams: [{ id: 'creativesites', name: 'CreativeSites AI Team' }],
    identities: [{ id: 'muse', name: 'Muse', role: 'Design lead', teamId: 'creativesites' }],
  });
  await call('POST', '/v1/adapters/fake', { command: process.execPath, args: [fixture], enabled: true });
  const board = await call('POST', '/v1/design-boards', { title: 'Checkout redesign', mode: 'greenfield', createdBy: 'winston' });
  boardId = board.json.id;
});

after(async () => {
  await rt.close();
  if (savedHome === undefined) delete process.env.MYAOS_HOME;
  else process.env.MYAOS_HOME = savedHome;
  fs.rmSync(dir, { recursive: true, force: true });
});

test('a new-design run: the agent writes a file in the board folder and it lands on the canvas', async () => {
  const started = await call('POST', `/v1/design-boards/${boardId}/runs`, {
    kind: 'new',
    prompt: 'myaos-design-test: new checkout home screen',
    agentId: 'muse',
    adapterId: 'fake',
    device: 'phone',
  });
  assert.equal(started.status, 202, JSON.stringify(started.json));
  assert.equal(started.json.kind, 'new');

  const frame = await waitFor(async () => {
    const b = await call('GET', `/v1/design-boards/${boardId}`);
    return (b.json.frames as any[]).find((f) => f.title === 'Home');
  });
  assert.equal(frame.device, 'phone');
  assert.equal(frame.authorId, 'muse', 'the frame is credited to the agent that wrote it');
  assert.equal(frame.width, 390);
  assert.ok(frame.htmlPath.startsWith(path.join(dir, 'home', 'designs', boardId)), 'saved in the board folder, not a project repo');

  const runs = await waitFor(async () => {
    const r = await call('GET', `/v1/design-boards/${boardId}/runs`);
    return r.json.length && r.json[0].state !== 'running' && r.json[0].state !== 'starting' ? r.json : null;
  });
  assert.equal(runs[0].prompt, 'myaos-design-test: new checkout home screen');
});

test('an iterate run edits the frame file in place and the frame gets a new version', async () => {
  const board = await call('GET', `/v1/design-boards/${boardId}`);
  const home = (board.json.frames as any[]).find((f) => f.title === 'Home');
  const started = await call('POST', `/v1/design-boards/${boardId}/runs`, {
    kind: 'iterate',
    action: 'update',
    prompt: 'myaos-design-test: update add a footer',
    frameIds: [home.id],
    agentId: 'muse',
    adapterId: 'fake',
  });
  assert.equal(started.status, 202, JSON.stringify(started.json));
  const updated = await waitFor(async () => {
    const b = await call('GET', `/v1/design-boards/${boardId}`);
    const f = (b.json.frames as any[]).find((x) => x.id === home.id);
    return f.version >= 2 ? f : null;
  });
  assert.match(updated.htmlContent, /<footer>Updated<\/footer>/);
});

test('bad requests are refused without starting a session', async () => {
  assert.equal((await call('POST', `/v1/design-boards/${boardId}/runs`, { kind: 'new', prompt: '' })).status, 400);
  assert.equal((await call('POST', `/v1/design-boards/${boardId}/runs`, { kind: 'from-code', prompt: 'recreate it', adapterId: 'fake', agentId: 'muse' })).status, 400, 'from-code needs a project');
  assert.equal((await call('POST', `/v1/design-boards/${boardId}/runs`, { kind: 'nonsense', prompt: 'x' })).status, 400);
});

test('design sessions may write only inside their board folder and run only read-only commands', () => {
  const board = '/tmp/designs/b1';
  assert.equal(designPermission(board, { kind: 'edit' }, { file_path: '/tmp/designs/b1/home.html' }).allow, true);
  assert.equal(designPermission(board, { kind: 'edit' }, { file_path: '/Users/x/project/src/App.tsx' }).allow, false);
  assert.equal(designPermission(board, { kind: 'edit' }, { file_path: '/tmp/designs/b1/../b2/x.html' }).allow, false);
  assert.equal(designPermission(board, { kind: 'read' }, { file_path: '/Users/x/project/src/App.tsx' }).allow, true);
  assert.equal(designPermission(board, { kind: 'execute' }, { command: 'rg Button src' }).allow, true);
  assert.equal(designPermission(board, { kind: 'execute' }, { command: 'npm install' }).allow, false);
  assert.equal(designPermission(board, { kind: 'execute' }, { command: 'ls; rm -rf /' }).allow, false);
});
